// da — Dansk (dinamarquês).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// TOM: **du**. O dinamarquês largou o *De* nos anos 1970 (a "du-reform" de lá não foi lei, foi costume),
// e hoje *De* só aparece com a rainha — num app de amigos, soaria como carta de banco.
//
// GÊNERO: o "você" não tem, e o particípio não concorda com quem lê ("Du er blevet inviteret" serve para
// todo mundo). A terceira pessoa tem (han / hun), e o dinamarquês NÃO adotou um neutro como o *hen*
// sueco — onde o sueco usou *hen*, a frase foi refeita para não precisar de pronome ("Den blokerede får
// ikke besked").
//
// NÚMEROS: `Intl.NumberFormat('da')` devolve `1.234.567` — latinos, com ponto.
//
// O DETECTOR DO TESTE DE IDIOMAS: o dinamarquês escreve "idé", "video", "bronze", "status" — palavras
// iguais às do português. Vai o das chaves, que é a regra de toda língua latina.
//
// PALAVRA COMPOSTA: o dinamarquês cola substantivos como o sueco e o alemão. Onde ficava longa demais para
// um rótulo, foi separada com preposição.
//
// ASPAS: »assim«, as do dinamarquês impresso. Não são apóstrofos, e não colidem com o `'` da chave.
//
// VOCABULÁRIO, decidido uma vez: comunidade = fællesskab, canal = kanal, sala de voz = talerum, chamada =
// opkald, conversa = samtale, mensagem = besked, senha = adgangskode, lixeira = papirkurv, tópico = tråd,
// conta = konto, administrador = administrator, dono = ejer, cargo = rolle, convite = invitation, perfil
// = profil, transmissão = udsendelse, tela = skærm, membro = medlem, pacote = pakke, enquete = afstemning,
// denúncia = indberetning (NÃO "anmeldelse", que também quer dizer resenha), vila = landsby, guarda-roupa
// = garderobe, cutucada = prik, capa = forsidebillede, recado (da tela de boas-vindas e do aviso) = opslag.
//
// SOM E VOZ SÃO DUAS PALAVRAS: stemme é a voz, lyd é o som de soundboard e de aviso.
//
// SELO E INSÍGNIA SEPARADOS: selo = segl (o da comunidade), insígnia = mærke (a da pessoa).

