  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) er fjernet fra Syden, fordi {quem} oplyser at have rettighederne. Hvis du havde tilladelse til at offentliggøre det, så svar her og forklar: dit svar bliver taget i betragtning. Indtil det er afklaret, forbliver indholdet fjernet. Vilkårene forklarer i afsnit 4, hvordan det fungerer: https://syden.chat/termos.html#direito-autoral',
