  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'Hele banden mod muldvarpekongen, der kommer op af hulerne i tre faser. Undgå mærkerne på jorden, snup de blålige jordklumper og kast dem tilbage. Banden vinder, eller ingen gør.',
  'Abóboras ladeira abaixo': 'Græskar ned ad bakken',
