  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Skift mellem ← og → i takt. For meget hast, og pusten slipper op.',
  'Ao calendário': 'Til kalenderen',
  'Ao guarda-roupa': 'Til garderoben',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Tryk på pilen, der dukker op, for at trække i rebet. Et fejltryk låser dig!',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'Tryk for at bremse hjulet. Det glider altid lidt, før det stopper.',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'Tryk uafbrudt for at svømme. Når der kommer en træstamme, så dyk!',
