  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Pump, når ringen lyser. Ude af takt slipper luften ud.',
  'Brasas da fogueira': 'Lejrbålets gløder',
  'Cabo de guerra': 'Tovtrækning',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'Hver padler på sin side: et tag skubber flåden mod den anden side. Sammen kører den ligeud. Snup gulerødderne!',
  'Caiu! Agora é torcer de longe.': 'Skudt ned! Nu er det at heppe på afstand.',
  'Canteiro que encolhe': 'Bed, der skrumper',
