  'Chão que desmorona': 'Gulv, der styrter sammen',
  'Chuva de cenouras': 'Gulerodsregn',
  'Cinco': 'Fem',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'Kaniner i små propelfly over køkkenhaven, der skyder med ærter og én styret gulerod ad gangen. To træffere kan du klare; den tredje skyder dig ned. Den sidste i luften vinder.',
  'Colheita em dupla': 'Høst for to',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'Spis tærten med din makker, skiftevis ◀ og ▶. Den første, der bliver færdig, vinder!',
  'Come as folhas': 'Spiser bladene',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'Kapsejlads med småbåde på søen, i bækken og i mangroven. Vandet er glat: slip speederen før svinget, pas på bredden, og brug strømmen og ringene. Solo mod uret og dine venners spøgelser.',
  'Corrida de cavalinho': 'Kæphestevæddeløb',
  'Dano da turma: {n}': 'Bandens skade: {n}',
  'De galho em galho': 'Fra gren til gren',
  'De que cor é a folha da cenoura?': 'Hvilken farve har gulerodstoppen?',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Gå ned, og snup gulerødderne. Undgå stenene!',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Find ud af, hvem der gemmer sig. Kun én chance: jo før, jo mere værd.',
  'Destampe os potes': 'Åbn glassene',
  'Desvie das brasas. São só três corações!': 'Undgå gløderne. Kun tre hjerter!',
  'Dez': 'Ti',
  'Do que uma planta precisa para crescer?': 'Hvad har en plante brug for for at gro?',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'To træffere kan du klare; den tredje skyder dig ned. Et skarpt sving tæt ved hegnet beskytter et øjeblik.',
  'Duas': 'To',
  'Duelo de aviõezinhos': 'Papirflyduel',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'To og to: den på grenen taber de modne jordbær, og den nedenunder griber dem med kurven.',
  'Em que dia é o aniversário do Syden?': 'Hvilken dag har Syden fødselsdag?',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Skub de andre ud af bedet. Kanten, der blinker, falder snart!',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Tving hønen op i et hjørne. Træt bliver hun langsom.',
  'Escolha a resposta certa antes que o tempo acabe.': 'Vælg det rigtige svar, før tiden løber ud.',
  'Escolher a torre': 'Vælg tårn',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Gem dig, hvor lygten ikke kigger. Den med lygten leder!',
  'Esconde-esconde na horta': 'Gemmeleg i køkkenhaven',
