  'Frear': 'Brems',
  'Fuga do rio': 'Flugt på floden',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'Undgå mærkerne på jorden. Gå hen over en blålig jordklump for at samle den op, og kast den tilbage på muldvarpen; én frøbombe pr. fase.',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Drej hvert låg mod pilen, hurtigt. Den forkerte vej strammer det igen.',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Husk dansens rækkefølge. Til sidst skal du sige, hvem der dansede på den markerede lampe.',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Husk, hvor hvert glas hører hjemme, og sæt dem alle på plads igen.',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Oppefra triller græskar; de, der klatrer, skifter spor for at undgå dem!',
