  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Følg dyrene fra hule til hule. Til sidst skal du pege på, hvor den med ballonen er.',
  'Silo': 'Silo',
  'Solte o cipó quando ele estiver na faixa clara.': 'Slip lianen, når den er i den lyse stribe.',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Slip, når majroen peger mod marken. Jo hurtigere den drejer, jo længere flyver den.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'Klatr op til vejrhanen. Fald og kragerne sender dig tilbage til den sidste etage.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'Klatr op ad laden over planker, baller og bjælker, der bevæger sig, helt op til vejrhanen, og undgå værktøj, der falder, og kragerne. Solo mod uret og dine venners spøgelser.',
