  '{n} voltas': '{n} omgange',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'Energien er dit liv og din turbo: at ramme kanten bruger den, den lyserøde stribe lader den op.',
  'A nave explodiu: a energia acabou.': 'Skibet eksploderede: energien slap op.',
  'Posição: {posicao} de {total}': 'Placering: {posicao} af {total}',
  'Escolher a pista': 'Vælg banen',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'Et ræs med gulerodsskibe på en svævende bane, meget hurtigere end karten. Energien er dit liv og din turbo: at ramme kanten bruger den, den lyserøde stribe lader den op, og at køre af banen er at falde. Solo, mod uret og dine venners spøgelser.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'Kartene i en lukket arena, hver med tre balloner. Tag kasserne og brug genstandene til at sprænge de andres balloner: den, der ikke har flere balloner, er ude, og den sidste tilbage vinder.',
  'Esquadrilha da toca': 'Hulens eskadrille',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'Små gulerodsfly mod skadedyrene i køkkenhaven: undvig frøene, snup forstærkningerne og skyd den mekaniske fugleskræmsel ned til sidst. Gruppen flyver de samme bølger, og eskadrillens point lægges sammen.',
