  'Minigolfe 3D': 'Minigolf 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Otte huller i 3D med ramper, slot og vindmølle, alle spiller det samme på samme tid. Træk for at sigte og give kraft, og giv slip. Den med færrest slag i alt vinder.',
  'Ver o buraco de cima': 'Se hullet oppefra',
  'Fora da pista! Mais uma tacada.': 'Uden for banen! Ét slag mere.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Træk til siden for at sigte og nedad for kraft, og giv slip. På tastaturet: piletasterne sigter, og mellemrum holdt nede giver kraften.',
  'Futebol dos coelhos': 'Kaninfodbold',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Fodbold på lille bane, set oppefra. Rør bolden for at drible, hold mellemrum nede for at skyde hårdere, og aflevér med X. I rummet fyldes holdene op med robotter.',
