  'Caça às pragas da horta': 'Skadedyrsjagt i køkkenhaven',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Krager og græshopper angriber køkkenhaven. Sigt og klik for at ramme dem, før de slipper væk: ammunitionen er talt, og hver bølge kommer hurtigere. Den med flest point vinder.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Sigt og klik på skadedyrene, før de slipper væk. Hvert skud bruger en gulerod.',
