  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Kaninerne forsvarer haven mod ræve, krager og en grævling. Gå sammen, slå i kombo og pas på hinanden: 1 til 4 personer.',
  'Pulo do coelho': 'Kaninhop',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Et platformløb: løb, hop og fald ikke. Solo mod uret og dine venners spøgelser; med holdet, live, på én bane eller alle tre.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Byt to grøntsager ved siden af hinanden for at samle tre eller flere ens. Stakken stiger uden stop: lad den ikke nå toppen. Med holdet sender kæder og komboer kasser til de andre.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Seks minigolfhuller, hvor alle spiller det samme på samme tid. Træk bolden tilbage og giv slip for at slå. Den med færrest slag vinder.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'På skift slår man med terningen og rykker rundt i haven. Saml gulerødder for at købe den gyldne gulerod, og efter hver runde spiller holdet et minispil. Den med flest gyldne gulerødder vinder.',
