  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Rejs rundt mellem Brasiliens delstatshovedstæder, køb byer og opkræv husleje af dem, der lander på dem. Med en hel region kan du bygge bygninger. Byt, byd på auktioner og løb ikke tør for penge.',
