  'Batalha naval': 'Sænke slagskibe',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Det klassiske domino for 2 til 4 personer (med 4 i hold af to). Læg brikkerne ved enderne, og den, der først går ud, får point for de andres brikker på hånden.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Truco fra São Paulo, med vendekort og trumfer, for 2 eller 4 i hold af to. Råb truco, hæv til seks, ni og tolv, eller stik af. Den, der får 12 point, vinder.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Brasiliansk dam: Det er tvungent at slå, både frem og tilbage, og dronningen går hele diagonalen. Rummet ser med.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Hver gemmer sin flåde og skyder i den andens hav. Ramt? Så skyder du igen. Den, der først sænker hele flåden, vinder. Rummet ser med.',
