  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'Tag ingredienserne fra kasserne, hak dem på brættet, steg og bag dem på komfuret og i ovnen uden at brænde dem, anret på tallerkenen og aflever i lugen. Alle får de samme bestillinger: den, der afleverer flest tallerkener på 3 minutter, vinder.',
