  "Diagnóstico do host": "Værtsdiagnose",
  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "Begrænsede logs fra Docker, SSH, logind og kernen fra de tre seneste opstarter. Kan indeholde IP-adresser.",
  "Atualizar diagnóstico": "Opdater diagnose",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "Intet øjebliksbillede endnu. Det indsamles næste gang boksen åbnes.",
  "Coletado em {data}": "Indsamlet {data}",
  "Medido pela {nome}": "Målt af {nome}",
  "Os mesmos números do painel do provedor. Inclui o disco, que o servidor não mede sozinho.": "De samme tal som i udbyderens kontrolpanel. Inklusive disken, som serveren ikke selv måler.",
  "Ações no servidor": "Handlinger på serveren",
  "O histórico da Hetzner: ligar, desligar e reiniciar, pelo painel ou pela API. Uma queda sem ação aqui não foi comandada por esses caminhos.": "Historikken hos Hetzner: tænd, sluk og genstart, fra kontrolpanelet eller API’et. Et nedbrud uden handling her blev ikke udløst ad de veje.",
