  'Quadros por segundo': "Billeder pr. sekund",
  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "Til når det automatiske valg tager fejl: opløsningen og billederne er dem, du vælger, fra start til slut i udsendelsen.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "Stemme- og kameraeffekterne, der laves på din computer, uden at sende noget til en server.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "Gulerodskommando",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "Løb og skyd med holdet: gulerodsskyderen sigter i otte retninger, granaten baner vejen, og den, der befrier de indespærrede kaninunger, får forstærkning. Dragen venter til sidst: 1 til 4 personer.",
  'Andar e mirar': "Gå og sigt",
  'Granada': "Granat",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "Hulens fangekælder",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "Kom igennem svampekongens hule sammen: rum fulde af dyr, en kiste med guleroden, der flyver ud og tilbage, knapper, der kræver to på én gang, og den låste dør. 1 til 4 personer.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "Hulens ring",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "Refleksboksning mod tre computermodstandere. Læs varslet for hvert slag, undvig eller blokér, og slå i åbningen. Slår du, når handsken glimter, fyldes stjernen til det hårde slag.",
  'Esquivar': "Undvig",
  'Abaixar e defender': "Duk og blokér",
  'Socar': "Slå",
  'Soco forte': "Hårdt slag",
  'Aperte os socos para levantar!': "Tryk på slagene for at rejse dig!",
  'Lutas vencidas: {n}': "Vundne kampe: {n}",
  'Nocaute!': "Knockout!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "Stjerneruten",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "Kaniner i rumskibe over en planets overflade og ud i rummet: skyd, hold skuddet inde for at låse målet, snurr for at afvise skud og vælg vej ved forgreningen. Gruppen flyver samme rute, og bossen venter til sidst.",
  'Pirueta': "Snurr",
  'Segure para travar a mira': "Hold inde for at låse målet",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "Køkkenhave-pinball",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "Et pinballbord i køkkenhaven: hold fjederen, sprut mod kålhovederne og vælt de tre gulerødder for at tænde kaninhullet, som slipper en bold mere ud. Tre bolde, og for meget rysten låser bordet.",
