  'Lendas da Toca': "Hulens legender",
  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "Et kort turbaseret RPG: hver person styrer én helt i gruppen. Vælg sammen, kombinér angreb og besejr slottets drage.",
