  'Bichos da Toca': "Hulens Dyr",
  'Ande pelo campo, faça amizade com os bichos do mato usando uma cenoura e monte uma equipe de até seis. Vença o desafio da casa azul e, na sala, lute com a equipe de um amigo.': "Gå rundt på marken, bliv venner med dyrene i det høje græs med en gulerod, og byg et hold på op til seks. Klar udfordringen i det blå hus, og kæmp i rummet mod en vens hold.",
