  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "En by, som ingen køber, kommer på auktion. At pantsætte en by giver penge, men så opkræver den ikke husleje.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "Hintet lyser brikken op, der skal flyttes. En opgave med hint giver ingen point; i løbet koster det 10 sekunder.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "Trumfen er værdien efter vendekortets og slår alle. Indbyrdes: ruder, spar, hjerter og klør, zap'en.",
  "A última nave de cada volta sai.": "Det sidste skib i hver omgang ryger ud.",
  "Abaixar": "Duk",
  "Acertos em sequência: {n}": "Rigtige i træk: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "Ryk efter terningen og køb hovedstaden, hvor du lander. Den, der lander på en andens by, betaler husleje.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "Hver række, kolonne og 3 × 3-blok har tallene 1 til 9 uden gentagelser.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "Alle får 3 kort. Den, der vinder 2 af de 3 runder, tager hånden.",
  "Campeonato": "Mesterskab",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "Med 11 point ser holdet kortene og beslutter, om det spiller elverhånden. Den, der når 12, vinder.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "Med hele regionen kan du bygge op til 4 bygninger: huslejen stiger for hver.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "Med stjerner bruger det hårde slag (★) dem alle på én gang og gør mere ondt.",
  "Dica": "Hint",
  "Dica: este problema não pontua": "Hint: denne opgave giver ingen point",
  "Dica: tira 10 segundos": "Hint: koster 10 sekunder",
  "Eliminação": "Udskilning",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "Læg en brik med samme tal ved en ende på bordet.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "Vælg feltet og så tallet. Blyanten noterer kun for dig.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "Undvig slaget og slå lige bagefter: det er kontraangrebet, og det giver en stjerne.",
  "Fora da corrida na volta {n}.": "Ude af løbet i omgang {n}.",
  "Força das cartas": "Kortenes styrke",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "Den største formue ved rundernes slutning vinder, eller den, der er tilbage.",
  "Iniciante": "Begynder",
  "Mestre": "Mester",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "I Serie giver hvert rigtigt svar en sværere opgave, og den første fejl afslutter den.",
  "O número pequeno no botão diz quantos ainda faltam.": "Det lille tal på knappen viser, hvor mange der mangler endnu.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "De fem baner i træk mod computeren, med point.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "Råb truco, og hånden er 3 værd. Den, der svarer, tager imod, stikker af eller hæver til 6, 9 eller 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "Den, der går ud, har ingen brikker tilbage og får point for de andres brikker på hånden. Er spillet låst, får den med færrest point på hånden dem.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "Passer ingen brik, så træk. Er der intet at trække, går turen videre.",
  "Sequência": "Serie",
  "Soque quando a luva brilhar: o golpe para e você ganha uma estrela.": "Slå, når handsken glimter: slaget stopper, og du får en stjerne.",
