  "Com a captura, cercar duas pedras do outro entre duas suas tira as duas; cinco capturas também vencem.": "Med fangst fjerner du to af modstanderens sten ved at indeslutte dem mellem to af dine; fem fangster vinder også.",
  "Com a restrição 3-3, as escuras não podem fazer dois três abertos de uma vez.": "Med 3-3-reglen må sort ikke lave to åbne treere på én gang.",
