  "Saara": "Sahara",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "Et hemmeligt dyr trækkes, og alle gætter på andre. Hvert gæt viser, hvad der passer med det hemmelige: klassen, føden, hvor det lever og vægten. Den, der rammer med færrest gæt, får flest point.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "En hemmelig dinosaur trækkes, og alle gætter på andre. Hvert gæt viser, hvad der passer med den hemmelige: perioden, føden, gruppen, længden og hvor den blev fundet. Den, der rammer med færrest gæt, får flest point.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "Et hemmeligt grundstof trækkes, og alle gætter på andre. Hvert gæt viser, hvad der passer med det hemmelige: familien, tilstandsformen, perioden, gruppen og atomnummeret. Den, der rammer med færrest gæt, får flest point.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "En hemmelig brasiliansk delstat trækkes, og alle gætter på andre. Hvert gæt viser afstanden og retningen til den hemmelige, regionen, befolkningen, arealet, kysten og grænsen til et andet land. Den, der rammer med færrest gæt, får flest point.",
